/*================================================
                PAGE SETTINGS
================================================*/

@page {
    size: A5 portrait;
    margin: 2mm;
}


body {
    font-family: Arial, Helvetica, sans-serif;
    font-size: 12px;
    color: #000;
    margin: 0;
    padding: 0;
}


.bill {
    position: relative;
    width: 100%;
    margin: 0;
    padding: 0;
}


.bill::before {
    content: "";
    position: absolute;
    top: 30%;
    left: 50%;
    width: 380px;
    height: 380px;
    transform: translate(-50%, -50%);
    background: url("/assets/selvi_hospital/images/hospital-logo.jpeg") no-repeat center center;
    background-size: contain;
    opacity: 0.12;
    z-index: 0;
    pointer-events: none;
}


.bill * {
    position: relative;
    z-index: 1;
}


/*================================================
                    HEADER
================================================*/

.hospital-name {
    text-align: center;
    font-size: 14px;
    font-weight: bold;
    line-height: 1;
    margin: 0;
    padding: 0;
}


.address,
.license {
    text-align: center;
    font-size: 10px;
    line-height: 1;
    margin: 0;
    padding: 0;
}


hr {
    border: none;
    border-top: 1px solid #000;
    margin: 2px 0;
}


/*================================================
                PATIENT DETAILS
================================================*/

.patient-table {
    width: 100%;
    border-collapse: collapse;
    margin: 0;
}


.patient-table td {
    font-size: 12px;
    padding: 0 2px;
    line-height: 0.15;
    vertical-align: middle;
    white-space: nowrap;
}


/*================================================
                    ITEMS TABLE
================================================*/

.items-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    margin: 0;
}


/* Header */

.items-table th {
    border-top: 1px solid #000;
    border-bottom: 1px solid #000;
    font-size: 12px;
    font-weight: normal;
    padding: 1px 2px;
    line-height: 0.80;
}


/* Body */

.items-table td {
    font-size: 11px;
    padding: 0 2px;
    line-height: 0.25;
    vertical-align: top;
    white-space: nowrap;
}


.items-table tbody tr {
    height: 16px;
}


/* Alignment */

.desc {
    text-align: left;
    word-wrap: break-word;
}


.center {
    text-align: center;
}


.right {
    text-align: right;
}


.left {
    text-align: left;
}


/*================================================
                TOTAL SECTION
================================================*/

.summary-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 2px;
}


.summary-table td {
    font-size: 12px;
    padding: 0 2px;
    line-height: 0.10;
    white-space: nowrap;
}


/*================================================
                    FOOTER
================================================*/

.footer-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 2px;
}


.footer-table td {
    width: 50%;
    font-size: 12px;
    padding-top: 2px;
    line-height: 0.10;
    margin-bottom: 15mm;
}


.footer {
    position: fixed;
    bottom: 0mm;
    right: 1mm;
    font-size: 10px;
    font-weight: bold;
}


.page-number:after {
    content: counter(page);
}


/*================================================
                PRINT CONTROL
================================================*/

.items-table tr {
    page-break-inside: avoid !important;
}


.summary-table,
.footer-table {
    page-break-before: avoid !important;
}


@media print {

    html,
    body {
        margin: 0 !important;
        padding: 0 !important;
    }

}

